To test `src/billing.js` effectively, we need to mock the external dependencies: the database (`pool`) and the `stripe` client. Since `src/billing.js` imports these dependencies directly, we can use Node's built-in `test` runner along with `mock` to intercept those calls.

Here is a test file `src/billing.test.js`.

```javascript
import { test, mock, describe, afterEach } from 'node:test';
import assert from 'node:assert';
import { chargeInvoice } from './billing.js';
import { pool } from './db.js';
import Stripe from 'stripe';

// Mock the database pool
mock.method(pool, 'query');

// Mock the Stripe client
// Since billing.js instantiates Stripe at the top level, we need to mock the instance
// that Stripe creates. We can mock the module export.
const mockStripeInstance = {
  paymentIntents: {
    create: mock.fn(),
  },
};
mock.module('stripe', {
  default: class {
    constructor() { return mockStripeInstance; }
  }
});

describe('billing.js', () => {
  afterEach(() => {
    mock.resetHistory();
  });

  test('chargeInvoice successfully charges a card', async () => {
    const invoiceId = 'inv_123';
    const mockInvoice = {
      rows: [{ amount_cents: 1000, currency: 'usd', customer_id: 'cus_abc' }]
    };
    const mockIntent = { id: 'pi_999', status: 'succeeded' };

    // Setup mocks
    pool.query.mock.mockImplementationOnce(() => Promise.resolve(mockInvoice));
    pool.query.mock.mockImplementationOnce(() => Promise.resolve()); // For the update
    mockStripeInstance.paymentIntents.create.mock.mockImplementationOnce(() => Promise.resolve(mockIntent));

    const result = await chargeInvoice(invoiceId);

    // Assertions
    assert.strictEqual(result.status, 'succeeded');
    assert.strictEqual(result.invoiceId, invoiceId);

    // Verify Stripe was called with correct params
    assert.strictEqual(mockStripeInstance.paymentIntents.create.mock.calls[0].arguments[0].amount, 1000);

    // Verify DB update was called
    assert.strictEqual(pool.query.mock.calls[1].arguments[0], 'update invoices set stripe_intent_id = $1 where id = $2');
  });

  test('chargeInvoice throws error if invoice not found', async () => {
    pool.query.mock.mockImplementationOnce(() => Promise.resolve({ rows: [] }));

    await assert.rejects(
      async () => await chargeInvoice('non_existent'),
      { message: 'no such invoice non_existent' }
    );
  });
});
```

### How to run this:
1. Save the code above as `src/billing.test.js`.
2. Run `npm test` (which uses `node --test`).

### Key Implementation Details:
*   **`mock.module`**: Because `stripe` is imported and instantiated at the top level of `billing.js`, we use `mock.module` to intercept the constructor. This ensures that when `billing.js` calls `new Stripe(...)`, it gets our `mockStripeInstance` instead of the real library.
*   **`mock.method`**: We use this on the `pool` object imported from `./db.js` to intercept the SQL queries.
*   **`mock.resetHistory()`**: This is crucial in `afterEach` to ensure that call counts and arguments from one test don't leak into the next.
